    goals = []
    while queue:
        (state_pegs, state_bridges), path = queue.popleft()
        if len(state_pegs) == 1:
            survivor = next(iter(state_pegs))
            if survivor != carrier:
                goals.append((len(path), survivor,
                              tuple(sorted(state_bridges)), path))
            continue
