            for action in macro:
                safe_step(child, action)
            child_key = key(child)
            if child_key == before:
                continue
            child_path = path + macro
            if child_key == target:
                return child_path, len(best), expanded
            if child_cost >= best.get(child_key, 10 ** 9):
                continue
            best[child_key] = child_cost
            serial += 1
